import { SyncOrchestrator } from './sync-orchestrator.ts';
import { ResponseBuilder } from './response-builder.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.50.0';
import {
  assertAdminManagerOrServiceRole,
  authorizationErrorResponse,
} from '../_shared/edgeAuthorization.ts';
import { disabledHostawayResponse, isHostawayIntegrationEnabled } from '../_shared/disabledIntegration.ts';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: corsHeaders });
  }

  if (!isHostawayIntegrationEnabled()) {
    return disabledHostawayResponse(corsHeaders);
  }

  try {
    const supabaseUrl = Deno.env.get('SUPABASE_URL') ?? '';
    const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '';
    const supabase = createClient(supabaseUrl, supabaseServiceKey);
    await assertAdminManagerOrServiceRole(req, supabase, supabaseServiceKey);

    const orchestrator = new SyncOrchestrator(supabaseUrl, supabaseServiceKey);

    try {
      // Inicializar log de sincronización
      await orchestrator.initializeSyncLog();

      // Realizar sincronización
      await orchestrator.performSync();

      // Finalizar con éxito
      await orchestrator.finalizeSyncLog(true);

      console.log('✅ Sincronización CORREGIDA completada exitosamente');
      console.log(`📊 Estadísticas finales:`, orchestrator.getStats());

      const stats = orchestrator.getStats();
      const cancellationSummary = orchestrator.getCancellationSummary();
      
      // Calcular fechas para la respuesta (ampliado a 30 días)
      const now = new Date();
      const startDate = now.toISOString().split('T')[0];
      const endDate = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

      const response = ResponseBuilder.buildSuccessResponse(
        stats,
        cancellationSummary,
        startDate,
        endDate,
        stats.reservations_processed
      );

      return new Response(JSON.stringify(response), {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 200
      });

    } catch (error) {
      console.error('❌ Error durante la sincronización:', error);
      
      await orchestrator.finalizeSyncLog(false, error);

      const response = ResponseBuilder.buildErrorResponse(error, orchestrator.getStats());

      return new Response(JSON.stringify(response), {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 500
      });
    }

  } catch (error) {
    const authResponse = authorizationErrorResponse(error, corsHeaders);
    if (authResponse) return authResponse;
    console.error('❌ Error crítico:', error);
    
    const response = ResponseBuilder.buildCriticalErrorResponse(error);

    return new Response(JSON.stringify(response), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      status: 500
    });
  }
});

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.50.0';
import { SyncStats } from './types.ts';
import { getHostawayToken, fetchAllHostawayReservations } from './hostaway-api.ts';
import { ImprovedReservationProcessor } from './improved-reservation-processor.ts';

export class SyncOrchestrator {
  private supabase;
  private stats: SyncStats;
  private syncLogId: string;
  private reservationProcessor: ImprovedReservationProcessor;

  constructor(supabaseUrl: string, supabaseServiceKey: string) {
    this.supabase = createClient(supabaseUrl, supabaseServiceKey);
    this.reservationProcessor = new ImprovedReservationProcessor(supabaseUrl, supabaseServiceKey);
    this.stats = {
      reservations_processed: 0,
      new_reservations: 0,
      updated_reservations: 0,
      cancelled_reservations: 0,
      tasks_created: 0,
      errors: [],
      tasks_details: [],
      reservations_details: []
    };
  }

  async initializeSyncLog(): Promise<void> {
    const { data: syncLog, error: logError } = await this.supabase
      .from('hostaway_sync_logs')
      .insert({
        sync_started_at: new Date().toISOString(),
        status: 'running'
      })
      .select()
      .single();

    if (logError) {
      console.error('Error creating sync log:', logError);
      throw logError;
    }

    this.syncLogId = syncLog.id;
    console.log(`🚀 INICIANDO SINCRONIZACIÓN SIMPLIFICADA (Log ID: ${syncLog.id})`);
  }

  async performSync(): Promise<void> {
    // PASO 1: Limpieza previa de duplicados existentes
    console.log(`🧹 PASO 1: Limpieza previa de duplicados`);
    await this.reservationProcessor.runPreSyncCleanup();

    // PASO 2: Obtener token de Hostaway
    console.log(`🔑 PASO 2: Obteniendo token de Hostaway`);
    const accessToken = await getHostawayToken();
    console.log('✅ Token obtenido exitosamente');

    // PASO 3: Calcular rango de fechas AMPLIADO (HOY + 30 días para capturar más reservas futuras)
    const today = new Date();
    const startDate = today.toISOString().split('T')[0]; // HOY
    const endDate = new Date(today.getTime() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]; // HOY + 30 días

    console.log(`📅 PASO 3: Período AMPLIADO - Desde HOY (${startDate}) hasta ${endDate} (30 días)`);
    console.log(`📅 OBJETIVO: Buscar reservas que hacen CHECKOUT en este período (ampliado para capturar más reservas futuras)`);

    // PASO 4: Obtener reservas de Hostaway (SOLO por checkout)
    console.log(`📥 PASO 4: Obteniendo reservas con checkout desde HOY hasta +30 días`);
    const reservations = await fetchAllHostawayReservations(accessToken, startDate, endDate);
    console.log(`📊 TOTAL DE RESERVAS ENCONTRADAS: ${reservations.length}`);

    if (reservations.length < 100) {
      console.log(`⚠️  ATENCIÓN: Solo se encontraron ${reservations.length} reservas. Se esperaban más de 150.`);
      console.log(`   - Verificar que las fechas son correctas: ${startDate} a ${endDate}`);
      console.log(`   - Verificar que Hostaway tiene reservas en este período`);
    }

    // PASO 5: Procesar cada reserva con verificación de duplicados
    console.log(`🔄 PASO 5: Procesando ${reservations.length} reservas con verificación de duplicados`);
    for (let i = 0; i < reservations.length; i++) {
      const reservation = reservations[i];
      try {
        await this.reservationProcessor.processReservation(reservation, this.stats, i, reservations.length);
      } catch (error) {
        console.error(`❌ Error procesando reserva ${reservation.id}:`, error);
        this.stats.errors.push(`Error en reserva ${reservation.id}: ${error.message}`);
      }
    }

    // PASO 6: Procesar reservas existentes sin tareas
    console.log(`🔄 PASO 6: Procesando reservas existentes sin tareas`);
    await this.processExistingReservationsWithoutTasks();

    console.log(`✅ SINCRONIZACIÓN COMPLETADA`);
    console.log(`📊 Estadísticas finales:`, this.stats);

    if (this.stats.reservations_processed < 100) {
      console.log(`⚠️  RESULTADO: Solo se procesaron ${this.stats.reservations_processed} reservas de ${reservations.length} encontradas`);
    }
  }

  async finalizeSyncLog(success: boolean, error?: Error): Promise<void> {
    const updateData = {
      sync_completed_at: new Date().toISOString(),
      status: success ? 'completed' : 'error',
      ...this.stats
    };

    if (error) {
      this.stats.errors.push(`Error general: ${error.message}`);
      updateData.errors = this.stats.errors;
    }

    await this.supabase
      .from('hostaway_sync_logs')
      .update(updateData)
      .eq('id', this.syncLogId);
  }

  async processExistingReservationsWithoutTasks(): Promise<void> {
    // Obtener reservas existentes sin tareas que deberían tenerlas
    // CORREGIDO: Filtrar correctamente los status inválidos
    const { data: reservationsWithoutTasks, error } = await this.supabase
      .from('hostaway_reservations')
      .select(`
        *,
        properties:property_id(*)
      `)
      .is('task_id', null)
      .gte('departure_date', new Date().toISOString().split('T')[0])
      .not('status', 'in', '("cancelled","inquiry","declined","expired")'); // Filtrar múltiples status inválidos

    if (error) {
      console.error('Error obteniendo reservas sin tareas:', error);
      this.stats.errors.push(`Error obteniendo reservas sin tareas: ${error.message}`);
      return;
    }

    if (!reservationsWithoutTasks || reservationsWithoutTasks.length === 0) {
      console.log('✅ No hay reservas existentes sin tareas');
      return;
    }

    console.log(`📋 Encontradas ${reservationsWithoutTasks.length} reservas existentes sin tareas`);

    // Procesar cada reserva sin tarea
    for (let i = 0; i < reservationsWithoutTasks.length; i++) {
      const dbReservation = reservationsWithoutTasks[i];
      
      // Convertir formato de BD a formato Hostaway para reutilizar lógica
      const hostawayReservation = {
        id: dbReservation.hostaway_reservation_id,
        listingMapId: dbReservation.properties?.hostaway_listing_id || 0,
        listingName: dbReservation.properties?.nombre || '',
        status: dbReservation.status,
        departureDate: dbReservation.departure_date,
        arrivalDate: dbReservation.arrival_date,
        reservationDate: dbReservation.reservation_date,
        cancellationDate: dbReservation.cancellation_date,
        nights: dbReservation.nights || 1,
        adults: dbReservation.adults || 1,
        guestName: 'Cliente sin nombre' // No tenemos guest name en BD
      };

      try {
        console.log(`🔄 Creando tarea faltante para reserva ${dbReservation.hostaway_reservation_id} (${i + 1}/${reservationsWithoutTasks.length})`);
        
        const taskId = await this.reservationProcessor.createMissingTaskForExistingReservation(
          hostawayReservation, 
          dbReservation.properties, 
          this.stats
        );

        if (taskId) {
          // Actualizar la reserva con el task_id
          await this.supabase
            .from('hostaway_reservations')
            .update({ task_id: taskId })
            .eq('id', dbReservation.id);
          
          console.log(`✅ Tarea creada y reserva actualizada: ${taskId}`);
        }
      } catch (error) {
        console.error(`❌ Error procesando reserva existente ${dbReservation.hostaway_reservation_id}:`, error);
        this.stats.errors.push(`Error en reserva existente ${dbReservation.hostaway_reservation_id}: ${error.message}`);
      }
    }
  }

  getStats(): SyncStats {
    return this.stats;
  }

  getCancellationSummary(): string {
    const cancelledReservations = this.stats.reservations_details?.filter(r => r.action === 'cancelled') || [];
    
    if (cancelledReservations.length > 0) {
      let summary = '';
      cancelledReservations.forEach(reservation => {
        const summaryLine = `- ${reservation.property_name} (${reservation.departure_date}): ${reservation.guest_name}`;
        summary += summaryLine + '\n';
      });
      return summary;
    }
    
    return 'No hubo cancelaciones';
  }
}

import { HostawayReservation, HostawayProperty } from './types.ts';

const HOSTAWAY_ACCOUNT_ID = 80687;
const HOSTAWAY_API_BASE = 'https://api.hostaway.com/v1';
const REQUEST_TIMEOUT = 30000; // 30 segundos
const MAX_RETRIES = 3;
const RETRY_DELAY = 1000; // 1 segundo

async function makeApiRequest(url: string, options: RequestInit, retries = MAX_RETRIES): Promise<Response> {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), REQUEST_TIMEOUT);
  
  try {
    const response = await fetch(url, {
      ...options,
      signal: controller.signal,
    });
    
    clearTimeout(timeoutId);
    
    if (!response.ok) {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }
    
    return response;
  } catch (error) {
    clearTimeout(timeoutId);
    
    if (retries > 0 && (error.name === 'AbortError' || error.message.includes('fetch'))) {
      console.log(`⚠️ Error en llamada API, reintentando... (${MAX_RETRIES - retries + 1}/${MAX_RETRIES})`);
      await new Promise(resolve => setTimeout(resolve, RETRY_DELAY));
      return makeApiRequest(url, options, retries - 1);
    }
    
    throw error;
  }
}

export async function getHostawayToken(): Promise<string> {
  console.log('Obteniendo token de Hostaway...');
  
  const clientId = Deno.env.get('HOSTAWAY_CLIENT_ID');
  const clientSecret = Deno.env.get('HOSTAWAY_CLIENT_SECRET');
  
  if (!clientId || !clientSecret) {
    throw new Error('Credenciales de Hostaway no configuradas');
  }

  const response = await makeApiRequest(`${HOSTAWAY_API_BASE}/accessTokens`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: new URLSearchParams({
      grant_type: 'client_credentials',
      client_id: clientId,
      client_secret: clientSecret,
      scope: 'general',
    }),
  });

  const data = await response.json();
  return data.access_token;
}

async function fetchHostawayReservationsByCheckout(token: string, startDate: string, endDate: string, offset: number = 0): Promise<HostawayReservation[]> {
  console.log(`📡 Obteniendo reservas por CHECKOUT desde ${startDate} hasta ${endDate}, offset: ${offset}`);
  
  const url = new URL(`${HOSTAWAY_API_BASE}/reservations`);
  url.searchParams.append('accountId', HOSTAWAY_ACCOUNT_ID.toString());
  
  // SOLO por fecha de salida (checkout) - cuando necesitamos limpieza
  url.searchParams.append('departureStartDate', startDate);
  url.searchParams.append('departureEndDate', endDate);
  url.searchParams.append('includeResolved', 'true');
  url.searchParams.append('limit', '200');
  url.searchParams.append('offset', offset.toString());

  console.log(`📡 URL de consulta: ${url.toString()}`);

  const response = await makeApiRequest(url.toString(), {
    headers: {
      'Authorization': `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
  });

  const data = await response.json();
  console.log(`📊 Respuesta de API: ${data.result?.length || 0} reservas encontradas`);
  
  // Mapear correctamente los datos de la API de Hostaway
  const mappedReservations: HostawayReservation[] = (data.result || []).map((apiReservation: any) => {
    const mapped: HostawayReservation = {
      id: apiReservation.id,
      listingMapId: apiReservation.listingMapId,
      listingName: apiReservation.listingName,
      status: apiReservation.status,
      arrivalDate: apiReservation.arrivalDate,
      departureDate: apiReservation.departureDate,
      reservationDate: apiReservation.reservationDate,
      cancellationDate: apiReservation.cancellationDate || null, // MAPEO CRÍTICO FALTANTE
      nights: apiReservation.nights,
      adults: apiReservation.adults,
      guestName: apiReservation.guestName
    };
    
    // Log detallado para debugging
    if (mapped.status === 'cancelled' || mapped.cancellationDate) {
      console.log(`🔍 RESERVA CANCELADA DETECTADA:`);
      console.log(`   - ID: ${mapped.id}`);
      console.log(`   - Status: ${mapped.status}`);
      console.log(`   - Cancellation Date: ${mapped.cancellationDate}`);
      console.log(`   - Property: ${mapped.listingName} (${mapped.listingMapId})`);
      console.log(`   - Guest: ${mapped.guestName}`);
    }
    
    return mapped;
  });
  
  console.log(`📊 Reservas mapeadas: ${mappedReservations.length}`);
  return mappedReservations;
}

export async function fetchAllHostawayReservations(token: string, startDate: string, endDate: string): Promise<HostawayReservation[]> {
  console.log(`🔍 BÚSQUEDA SIMPLIFICADA DE RESERVAS`);
  console.log(`📅 Período de checkout: ${startDate} hasta ${endDate} (HOY + 14 días)`);
  
  let allReservations: HostawayReservation[] = [];
  let offset = 0;
  let hasMore = true;

  // Buscar SOLO por fecha de checkout (cuando necesitamos limpieza)
  console.log(`📤 Buscando reservas que hacen CHECKOUT en el período...`);
  while (hasMore) {
    const reservations = await fetchHostawayReservationsByCheckout(token, startDate, endDate, offset);
    allReservations = allReservations.concat(reservations);
    
    console.log(`📊 Página ${Math.floor(offset/200) + 1}: ${reservations.length} reservas (total acumulado: ${allReservations.length})`);
    
    hasMore = reservations.length === 200;
    offset += 200;
  }

  console.log(`🎯 RESULTADO FINAL:`);
  console.log(`   - Total de reservas encontradas: ${allReservations.length}`);
  console.log(`   - Período buscado: ${startDate} a ${endDate}`);
  console.log(`   - Búsqueda: SOLO por fechas de CHECKOUT`);

  // Log detallado de estados
  console.log(`📋 Estados de reservas encontradas:`);
  const statusCounts = allReservations.reduce((acc, r) => {
    acc[r.status] = (acc[r.status] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);
  
  Object.entries(statusCounts).forEach(([status, count]) => {
    console.log(`   - ${status}: ${count} reservas`);
  });

  // Muestra de reservas para verificación
  console.log(`📋 Primeras 10 reservas encontradas:`);
  allReservations.slice(0, 10).forEach((r, i) => {
    console.log(`   ${i+1}. ID: ${r.id}, checkout: ${r.departureDate}, status: ${r.status}, listing: ${r.listingMapId}, guest: ${r.guestName}`);
  });

  return allReservations;
}

export async function fetchHostawayProperties(token: string): Promise<HostawayProperty[]> {
  console.log('Obteniendo propiedades de Hostaway con timeouts...');
  
  const url = new URL(`${HOSTAWAY_API_BASE}/listings`);
  url.searchParams.append('accountId', HOSTAWAY_ACCOUNT_ID.toString());

  const response = await makeApiRequest(url.toString(), {
    headers: {
      'Authorization': `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
  });

  const data = await response.json();
  return data.result || [];
}

import { HostawayReservation, SyncStats } from './types.ts';
import { 
  findPropertyByHostawayId, 
  getExistingReservation,
  insertReservation,
  createTaskForReservation,
  deleteTaskIfPending,
} from './database-operations.ts';
import { shouldCreateTaskForReservation, getTaskCreationReason } from './reservation-validator.ts';
import { handleReservationStatusChange, handleUnchangedReservation } from './reservation-status-handler.ts';
import { DuplicatePreventionService } from './duplicate-prevention.ts';
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.50.0";

export class ImprovedReservationProcessor {
  private duplicateChecker: DuplicatePreventionService;
  private supabase;

  constructor(supabaseUrl: string, supabaseServiceKey: string) {
    this.duplicateChecker = new DuplicatePreventionService(supabaseUrl, supabaseServiceKey);
    // Crear cliente Supabase para operaciones directas
    this.supabase = createClient(supabaseUrl, supabaseServiceKey);
  }

  async processReservation(
    reservation: HostawayReservation, 
    stats: SyncStats,
    reservationIndex: number,
    totalReservations: number
  ): Promise<void> {
    console.log(`\n🔄 PROCESANDO RESERVA ${reservation.id} (${reservationIndex + 1}/${totalReservations})`);
    console.log(`   - Propiedad: ${reservation.listingName || 'N/A'} (ID: ${reservation.listingMapId})`);
    console.log(`   - Estado: ${reservation.status}`);
    console.log(`   - Check-out: ${reservation.departureDate}`);
    console.log(`   - Huésped: ${reservation.guestName}`);

    // Buscar la propiedad
    const property = await findPropertyByHostawayId(
      reservation.listingMapId, 
      reservation.listingName || undefined
    );
    
    if (!property) {
      const errorMsg = `Propiedad no encontrada: listingMapId ${reservation.listingMapId}, nombre: ${reservation.listingName || 'N/A'}`;
      console.warn(`⚠️ ${errorMsg}`);
      stats.errors.push(errorMsg);
      return;
    }

    console.log(`✅ Propiedad encontrada: ${property.nombre}`);

    // VERIFICACIÓN CRÍTICA: Si la reserva está cancelada, limpiar task_id ANTES de verificar duplicados
    const isCurrentlyCancelled = reservation.status === 'cancelled' || reservation.cancellationDate;
    
    if (isCurrentlyCancelled) {
      console.log(`🚫 RESERVA CANCELADA DETECTADA: ${reservation.id} - Verificando si tiene tarea asignada`);
      
      const existingReservation = await getExistingReservation(reservation.id);
      
      if (existingReservation && existingReservation.task_id) {
        console.log(`🗑️ ELIMINANDO TAREA DE RESERVA CANCELADA: ${existingReservation.task_id}`);
        
        try {
          const taskId = existingReservation.task_id;
          
          // Verificar si otras reservas usan la misma tarea sin desvincular primero.
          const { data: otherReservations, error: checkError } = await this.supabase
            .from('hostaway_reservations')
            .select('id')
            .eq('task_id', taskId)
            .neq('id', existingReservation.id);
            
          if (checkError) {
            throw checkError;
          } else if (otherReservations && otherReservations.length === 0) {
            // El FK ON DELETE SET NULL desvincula la reserva en la misma operación.
            const deleted = await deleteTaskIfPending(taskId);
            if (deleted) {
              console.log(`✅ Tarea pending eliminada: ${taskId}`);
            } else {
              console.log(`🛡️ Tarea ${taskId} conservada: ya comenzó, terminó o su estado no es seguro para borrar`);
            }
          } else {
            console.log(`⚠️ Tarea ${taskId} no eliminada - está siendo usada por ${otherReservations?.length || 0} otras reservas`);
          }

          const { error: reservationUpdateError } = await this.supabase
            .from('hostaway_reservations')
            .update({
              status: reservation.status,
              cancellation_date: reservation.cancellationDate || null,
              last_sync_at: new Date().toISOString(),
            })
            .eq('id', existingReservation.id);
          if (reservationUpdateError) throw reservationUpdateError;
          
          stats.cancelled_reservations++;
          
          // Agregar detalles de cancelación
          if (!stats.reservations_details) stats.reservations_details = [];
          stats.reservations_details.push({
            reservation_id: reservation.id,
            property_name: property.nombre,
            guest_name: reservation.guestName,
            listing_id: reservation.listingMapId,
            status: reservation.status,
            arrival_date: reservation.arrivalDate,
            departure_date: reservation.departureDate,
            action: 'cancelled'
          });

          console.log(`✅ Reserva cancelada procesada correctamente: ${reservation.id}`);
        } catch (error) {
          console.error(`❌ Error procesando reserva cancelada ${reservation.id}:`, error);
          stats.errors.push(`Error procesando cancelación ${reservation.id}: ${error.message}`);
        }
      }
      
      // Para reservas canceladas, no crear nuevas tareas ni continuar procesando
      if (!existingReservation) {
        // Si es una nueva reserva cancelada, crearla sin tarea
        console.log(`📝 Creando nueva reserva cancelada sin tarea: ${reservation.id}`);
        
        const reservationData = {
          hostaway_reservation_id: reservation.id,
          property_id: property.id,
          cliente_id: property.cliente_id,
          arrival_date: reservation.arrivalDate,
          departure_date: reservation.departureDate,
          reservation_date: reservation.reservationDate,
          cancellation_date: reservation.cancellationDate || null,
          nights: reservation.nights,
          status: reservation.status,
          adults: reservation.adults,
          task_id: null,
          last_sync_at: new Date().toISOString()
        };

        await insertReservation(reservationData);
        stats.cancelled_reservations++;
        
        // Agregar detalles de reserva cancelada
        if (!stats.reservations_details) stats.reservations_details = [];
        stats.reservations_details.push({
          reservation_id: reservation.id,
          property_name: property.nombre,
          guest_name: reservation.guestName,
          listing_id: reservation.listingMapId,
          status: reservation.status,
          arrival_date: reservation.arrivalDate,
          departure_date: reservation.departureDate,
          action: 'created'
        });
      }
      
      stats.reservations_processed++;
      return; // Salir temprano para reservas canceladas
    }

    // VERIFICACIÓN CRÍTICA: Comprobar duplicados SOLO para reservas NO canceladas
    const isDuplicate = await this.duplicateChecker.checkForExistingTask(
      reservation.id,
      property.nombre,
      reservation.departureDate
    );

    if (isDuplicate) {
      console.log(`🚫 RESERVA DUPLICADA - SALTANDO CREACIÓN`);
      return;
    }

    // Verificar si ya existe la reserva en nuestra base de datos
    const existingReservation = await getExistingReservation(reservation.id);

    if (existingReservation) {
      console.log(`📝 Reserva existente encontrada: ${existingReservation.id}`);
      await this.handleExistingReservation(reservation, existingReservation, property, stats);
    } else {
      console.log(`🆕 Nueva reserva - Creando tarea`);
      await this.handleNewReservation(reservation, property, stats);
    }

    stats.reservations_processed++;
  }

  private async handleNewReservation(
    reservation: HostawayReservation,
    property: any,
    stats: SyncStats
  ): Promise<void> {
    try {
      // VALIDACIÓN CRÍTICA: Verificar si debe crear tarea
      const shouldCreateTask = shouldCreateTaskForReservation(reservation);
      console.log(`🔍 ¿Crear tarea para reserva ${reservation.id}? ${shouldCreateTask}`);
      console.log(`📋 Motivo: ${getTaskCreationReason(reservation)}`);
      
      let taskId = null;
      
      if (shouldCreateTask) {
        // Crear la tarea solo si pasa la validación
        const task = await createTaskForReservation(reservation, property);
        taskId = task.id;
        stats.tasks_created++;
        console.log(`✅ Tarea creada: ${task.id}`);
        
        // Agregar detalles de la tarea creada
        if (!stats.tasks_details) stats.tasks_details = [];
        stats.tasks_details.push({
          reservation_id: reservation.id,
          property_name: property.nombre,
          task_id: task.id,
          task_date: reservation.departureDate,
          guest_name: reservation.guestName,
          listing_id: reservation.listingMapId,
          status: reservation.status
        });
      } else {
        console.log(`⏭️ NO se crea tarea: ${getTaskCreationReason(reservation)}`);
      }

      // Crear la reserva con referencia a la tarea (o sin tarea si es cancelada)
      const reservationData = {
        hostaway_reservation_id: reservation.id,
        property_id: property.id,
        cliente_id: property.cliente_id,
        arrival_date: reservation.arrivalDate,
        departure_date: reservation.departureDate,
        reservation_date: reservation.reservationDate,
        cancellation_date: reservation.cancellationDate || null,
        nights: reservation.nights,
        status: reservation.status,
        adults: reservation.adults,
        task_id: taskId, // Puede ser null para reservas canceladas
        last_sync_at: new Date().toISOString()
      };

      await insertReservation(reservationData);
      
      stats.new_reservations++;
      
      // Agregar detalles de reserva
      if (!stats.reservations_details) stats.reservations_details = [];

      stats.reservations_details.push({
        reservation_id: reservation.id,
        property_name: property.nombre,
        guest_name: reservation.guestName,
        listing_id: reservation.listingMapId,
        status: reservation.status,
        arrival_date: reservation.arrivalDate,
        departure_date: reservation.departureDate,
        action: 'created'
      });

      if (taskId) {
        console.log(`✅ Nueva reserva y tarea creadas exitosamente`);
      } else {
        console.log(`✅ Nueva reserva creada (sin tarea por estado: ${reservation.status})`);
      }

    } catch (error) {
      const errorMsg = `Error creando nueva reserva ${reservation.id}: ${error.message}`;
      console.error(`❌ ${errorMsg}`);
      stats.errors.push(errorMsg);
    }
  }

  private async handleExistingReservation(
    reservation: HostawayReservation,
    existingReservation: any,
    property: any,
    stats: SyncStats
  ): Promise<void> {
    // VERIFICACIÓN CRÍTICA: Si la reserva está cancelada pero tiene tarea, eliminarla
    const isCurrentlyCancelled = reservation.status === 'cancelled' || reservation.cancellationDate;
    
    if (isCurrentlyCancelled && existingReservation.task_id) {
      console.log(`🚫 DETECTADA RESERVA CANCELADA CON TAREA: ${reservation.id}`);
      console.log(`   - Status: ${reservation.status}`);
      console.log(`   - Cancellation Date: ${reservation.cancellationDate || 'NULL'}`);
      console.log(`   - Task ID a eliminar: ${existingReservation.task_id}`);
      
      // Aplicar la política de cancelación también en esta ruta defensiva.
      try {
        const deleted = await deleteTaskIfPending(existingReservation.task_id);

        if (!deleted) {
          console.log(`🛡️ Tarea ${existingReservation.task_id} conservada: ya comenzó, terminó o su estado no es seguro para borrar`);
        } else {
          console.log(`✅ Tarea pending eliminada: ${existingReservation.task_id}`);
        }

        const { error: reservationUpdateError } = await this.supabase
          .from('hostaway_reservations')
          .update({
            status: reservation.status,
            cancellation_date: reservation.cancellationDate || null,
            last_sync_at: new Date().toISOString(),
          })
          .eq('id', existingReservation.id);
        if (reservationUpdateError) throw reservationUpdateError;

        stats.cancelled_reservations++;

        if (!stats.reservations_details) stats.reservations_details = [];
        stats.reservations_details.push({
          reservation_id: reservation.id,
          property_name: property.nombre,
          guest_name: reservation.guestName,
          listing_id: reservation.listingMapId,
          status: reservation.status,
          arrival_date: reservation.arrivalDate,
          departure_date: reservation.departureDate,
          action: 'cancelled'
        });

        console.log(`✅ Reserva cancelada procesada correctamente: ${reservation.id}`);
      } catch (error) {
        console.error(`❌ Error procesando reserva cancelada ${reservation.id}:`, error);
        stats.errors.push(`Error procesando cancelación ${reservation.id}: ${error.message}`);
      }

      return; // Salir temprano, no procesar más cambios
    }

    // Crear datos de reserva actualizados para reservas NO canceladas
    const reservationData = {
      hostaway_reservation_id: reservation.id,
      property_id: property.id,
      cliente_id: property.cliente_id,
      arrival_date: reservation.arrivalDate,
      departure_date: reservation.departureDate,
      reservation_date: reservation.reservationDate,
      cancellation_date: reservation.cancellationDate || null,
      nights: reservation.nights,
      status: reservation.status,
      adults: reservation.adults,
      last_sync_at: new Date().toISOString()
    };

    // Verificar si hay cambios significativos
    const hasChanges = 
      existingReservation.status !== reservation.status ||
      existingReservation.departure_date !== reservation.departureDate ||
      existingReservation.arrival_date !== reservation.arrivalDate ||
      existingReservation.cancellation_date !== (reservation.cancellationDate || null);

    if (hasChanges) {
      console.log(`📝 Cambios detectados - usando handleReservationStatusChange`);
      await handleReservationStatusChange(
        reservation, 
        existingReservation, 
        property, 
        reservationData, 
        stats
      );
    } else {
      console.log(`✅ Sin cambios - usando handleUnchangedReservation`);
      await handleUnchangedReservation(
        reservation, 
        existingReservation, 
        property, 
        reservationData, 
        stats
      );
    }
  }

  async runPreSyncCleanup(): Promise<void> {
    console.log(`🧹 EJECUTANDO LIMPIEZA PREVIA A LA SINCRONIZACIÓN...`);
    await this.duplicateChecker.cleanupExistingDuplicates();
  }

  async createMissingTaskForExistingReservation(
    reservation: HostawayReservation,
    property: any,
    stats: SyncStats
  ): Promise<string | null> {
    console.log(`📋 Evaluando tarea faltante para reserva existente: ${reservation.id}`);
    console.log(`📋 Propiedad: ${property.nombre}, Status: ${reservation.status}`);
    
    // USAR LA VALIDACIÓN CORRECTA Y COMPLETA
    const shouldCreateTask = shouldCreateTaskForReservation(reservation);
    console.log(`🔍 ¿Crear tarea faltante? ${shouldCreateTask}`);
    console.log(`📋 Motivo: ${getTaskCreationReason(reservation)}`);
    
    if (!shouldCreateTask) {
      console.log(`⏭️ No se crea tarea: ${getTaskCreationReason(reservation)}`);
      return null;
    }

    try {
      const task = await createTaskForReservation(reservation, property);
      stats.tasks_created++;
      
      // Agregar detalles de la tarea creada
      if (!stats.tasks_details) stats.tasks_details = [];
      stats.tasks_details.push({
        reservation_id: reservation.id,
        property_name: property.nombre,
        task_id: task.id,
        task_date: reservation.departureDate,
        guest_name: reservation.guestName,
        listing_id: reservation.listingMapId,
        status: reservation.status
      });
      
      console.log(`✅ Tarea faltante creada: ${task.id} para fecha: ${reservation.departureDate}`);
      return task.id;
    } catch (error) {
      const errorMsg = `Error creando tarea faltante para reserva ${reservation.id}: ${error.message}`;
      console.error(`❌ ${errorMsg}`);
      stats.errors.push(errorMsg);
      return null;
    }
  }
}

