export async function insertReservation(reservationData: any) {
  // Validar integridad referencial antes de insertar
  if (reservationData.property_id && reservationData.cliente_id) {
    const validation = await validatePropertyAndClient(reservationData.property_id, reservationData.cliente_id);
    if (!validation.valid) {
      throw new Error(`Validación de integridad fallida: ${validation.errors.join(', ')}`);
    }
  }
  
  return await supabase
    .from('hostaway_reservations')
    .insert(reservationData);
}

export async function updateReservation(reservationId: string, reservationData: any) {
  // Validar integridad referencial antes de actualizar
  if (reservationData.property_id && reservationData.cliente_id) {
    const validation = await validatePropertyAndClient(reservationData.property_id, reservationData.cliente_id);
    if (!validation.valid) {
      throw new Error(`Validación de integridad fallida: ${validation.errors.join(', ')}`);
    }
  }
  
  return await supabase
    .from('hostaway_reservations')
    .update(reservationData)
    .eq('id', reservationId);
}

export async function deleteTaskIfPending(taskId: string): Promise<boolean> {
  const { data: task, error: taskError } = await supabase
    .from('tasks')
    .select('status')
    .eq('id', taskId)
    .maybeSingle();

  if (taskError) throw taskError;
  if (!task || !canDeleteTaskAfterPmsCancellation(task.status)) return false;

  const { data: deletedTask, error: deleteError } = await supabase
    .from('tasks')
    .delete()
    .eq('id', taskId)
    .eq('status', task.status)
    .select('id')
    .maybeSingle();

  if (deleteError) throw deleteError;
  return Boolean(deletedTask);
}

export async function updateTaskDate(taskId: string, newDate: string) {
  console.log(`📅 Actualizando fecha de tarea ${taskId} a ${newDate}`);
  
  // Primero obtener la tarea original para comparar
  const { data: originalTask, error: originalError } = await supabase
    .from('tasks')
    .select('*')
    .eq('id', taskId)
    .single();

  if (originalError) {
    console.error('❌ Error obteniendo tarea original:', originalError);
    throw originalError;
  }

  // Actualizar solo la fecha sin disparar notificaciones automáticas
  const { data: task, error } = await supabase
    .from('tasks')
    .update({ 
      date: newDate,
      updated_at: new Date().toISOString()
    })
    .eq('id', taskId)
    .select()
    .single();

  if (error) {
    console.error('❌ Error actualizando fecha de tarea:', error);
    throw error;
  }

  // Solo enviar email de cambio de horario si la tarea tiene limpiador asignado
  // y es una actualización de Hostaway (no una cancelación)
  if (originalTask.cleaner_id && originalTask.date !== newDate) {
    console.log(`📧 Enviando email de cambio de horario por sincronización Hostaway`);
    try {
      // Obtener información del limpiador
      const { data: cleaner, error: cleanerError } = await supabase
        .from('cleaners')
        .select('email, name')
        .eq('id', originalTask.cleaner_id)
        .single();

      if (!cleanerError && cleaner) {
        await supabase.functions.invoke('send-task-schedule-change-email', {
          body: {
            taskId: task.id,
            taskDate: task.date,
            taskStartTime: task.start_time,
            taskEndTime: task.end_time,
            propertyName: task.property,
            propertyAddress: task.address,
            cleanerName: cleaner.name,
            cleanerEmail: cleaner.email,
            originalDate: originalTask.date,
            originalStartTime: originalTask.start_time,
            originalEndTime: originalTask.end_time,
            reason: 'Actualización automática por cambio en reserva Hostaway'
          }
        });
        console.log(`✅ Email de cambio de horario enviado a ${cleaner.name}`);
      }
    } catch (emailError) {
      console.error(`❌ Error enviando email de cambio de horario:`, emailError);
      // No falla la operación si el email no se puede enviar
    }
  }

  console.log(`✅ Fecha de tarea actualizada exitosamente: ${task.id} -> ${task.date}`);
  return task;
}

const DELETABLE_TASK_STATUS = 'pending';

export function normalizeTaskStatus(status: string | null | undefined): string {
  return String(status ?? '')
    .trim()
    .toLowerCase()
    .replace(/_/g, '-');
}

/**
 * PMS cancellations may only remove tasks that have not started yet.
 * Unknown states are preserved deliberately: destructive integrations fail closed.
 */
export function canDeleteTaskAfterPmsCancellation(
  status: string | null | undefined,
): boolean {
  return normalizeTaskStatus(status) === DELETABLE_TASK_STATUS;
}

import { HostawayReservation } from './types.ts';

/**
 * Determines if a task should be created for a reservation based on its status
 */
export function shouldCreateTaskForReservation(reservation: HostawayReservation): boolean {
  console.log(`🔍 Evaluando si crear tarea para reserva ${reservation.id}: status="${reservation.status}", cancellationDate="${reservation.cancellationDate || 'NULL'}"`);
  
  // REGLA CRÍTICA HOSTAWAY: Solo 3 estados posibles: new, modified, cancelled
  const validHostawayStatuses = ['new', 'modified', 'cancelled'];
  const statusLower = reservation.status.toLowerCase();
  
  if (!validHostawayStatuses.includes(statusLower)) {
    console.log(`❌ ESTADO INVÁLIDO: ${reservation.id} tiene status desconocido: ${reservation.status}`);
    return false;
  }
  
  // REGLA 1: Si status es 'cancelled', NO crear tarea NUNCA
  if (statusLower === 'cancelled') {
    console.log(`❌ NO CREAR TAREA: Reserva ${reservation.id} status=cancelled`);
    return false;
  }
  
  // REGLA 2: Si tiene fecha de cancelación, NO crear tarea NUNCA (independientemente del status)
  if (reservation.cancellationDate) {
    console.log(`❌ NO CREAR TAREA: Reserva ${reservation.id} tiene cancellation_date: ${reservation.cancellationDate}`);
    console.log(`❌ Status actual: ${reservation.status} - IGNORADO, cancellation_date prevalece`);
    return false;
  }
  
  // REGLA 3: Solo 'new' y 'modified' CREAN tareas
  if (statusLower === 'new') {
    console.log(`✅ CREAR TAREA: Reserva ${reservation.id} status=new`);
    return true;
  }
  
  if (statusLower === 'modified') {
    console.log(`✅ CREAR TAREA: Reserva ${reservation.id} status=modified`);
    return true;
  }
  
  // Solo debería llegar aquí si hay un error en la lógica anterior
  console.log(`❌ ERROR LÓGICO: Llegó al final con status inesperado: ${reservation.status}`);
  return false;
}

/**
 * Explains why a task creation decision was made
 */
export function getTaskCreationReason(reservation: HostawayReservation): string {
  // PRIMERA PRIORIDAD: Verificar fecha de cancelación
  if (reservation.cancellationDate) {
    return `Reserva cancelada (fecha de cancelación: ${reservation.cancellationDate})`;
  }
  
  const statusLower = reservation.status.toLowerCase();
  
  // Verificar cancelación por status
  if (statusLower === 'cancelled') {
    return 'Reserva cancelada (status: cancelled)';
  }
  
  // Estados válidos que crean tareas
  if (statusLower === 'new') {
    return 'Reserva nueva - se crea tarea';
  }
  
  if (statusLower === 'modified') {
    return 'Reserva modificada - se crea tarea';
  }
  
  // Estados inválidos de Hostaway
  const validHostawayStatuses = ['new', 'modified', 'cancelled'];
  if (!validHostawayStatuses.includes(statusLower)) {
    return `Estado desconocido de Hostaway: ${reservation.status}`;
  }
  
  return 'Status procesado correctamente';
}

import { HostawayReservation, SyncStats, ReservationDetail } from './types.ts';
