      }
    } catch (error) {
      console.error(`Error eliminando tarea ${existingReservation.task_id}:`, error);
      stats.errors.push(`No se pudo aplicar de forma segura la cancelación a la tarea ${existingReservation.task_id}: ${error.message}`);
