/**
 * Creates a missing task for an existing reservation
 */
export async function createMissingTask(
  reservation: HostawayReservation,
  property: any,
  stats: SyncStats
): Promise<string | null> {
  if (!shouldCreateTaskForReservation(reservation)) {
    return null;
  }

